/**
 * Native file tools for direct tool calls (`POST /v1/tools/:toolName`).
 * The tools themselves are the SDK's `createFileSystemTools`; this module
 * only maps the names a caller may use onto them and applies the agent's
 * `tools` allowlist the way a turn does.
 */
import { homedir } from "node:os";
import path from "node:path";
import { isRecord } from "./is-record.js";
const DIRECT_FILE_TOOL_NAMES = {
    read: "Read",
    Read: "Read",
    ls: "LS",
    LS: "LS",
    glob: "Glob",
    Glob: "Glob",
    grep: "Grep",
    Grep: "Grep",
    write: "Write",
    Write: "Write",
    StrReplace: "StrReplace",
    delete: "Delete",
    Delete: "Delete",
};
/** The `tools` names that grant each file tool in a turn. */
const ALLOWLIST_GRANTS = {
    Read: "read",
    LS: "ls",
    Glob: "glob",
    Grep: "grep",
    Write: "edit",
    StrReplace: "edit",
    Delete: "delete",
};
/**
 * The file tool a direct call runs. `edit` with `fileText` or `contents`
 * is Write; any other `edit` is StrReplace.
 */
export function directFileToolName(name, input) {
    if (name === "edit") {
        const args = isRecord(input) ? input : {};
        return "fileText" in args || "contents" in args ? "Write" : "StrReplace";
    }
    return DIRECT_FILE_TOOL_NAMES[name];
}
/** Omitted `tools` allows every file tool, as it does in a turn. */
export function directFileToolAllowed(name, tools) {
    return tools === undefined || tools.includes(ALLOWLIST_GRANTS[name]);
}
/**
 * Where the SDK spills large WebFetch and WebSearch output for a host
 * cwd. Direct Read calls on a host-disk agent may read it.
 */
export function hostAgentToolsDir(cwd) {
    const slug = cwd
        .replace(/[^a-zA-Z0-9]/g, "-")
        .replace(/-+/g, "-")
        .replace(/^-+|-+$/g, "");
    return path.join(homedir(), ".cursor", "projects", slug, "agent-tools");
}
